export function checkToken(token, now = Date.now()) {
  if (!token) return { ok: false, reason: 'missing' }
  const [user, exp] = token.split('.')
  if (!user || !exp) return { ok: false, reason: 'malformed' }
  if (Number(exp) < now) return { ok: false, reason: 'expired' }
  return { ok: true, user }
}

