class RefundError(Exception):
    pass


def refund_amount(paid_cents, days_since_purchase, reason):
    if paid_cents <= 0:
        raise RefundError("nothing to refund")
    if reason == "defective":
        return paid_cents
    if days_since_purchase > 30:
        raise RefundError("refund window closed")
    if days_since_purchase > 14:
        return paid_cents // 2
    return paid_cents

