export async function charge(client, cents) {
  try {
    const res = await client.charge({ amount: cents })
    if (res.status === 'declined') return { ok: false, error: 'card_declined' }
    return { ok: true, id: res.id }
  } catch (err) {
    return { ok: false, error: 'network', detail: String(err) }
  }
}

